-- ============================================================================
-- Aromati — content seed
--
-- GENERATED by tools/gen-seed-sql.mjs from data/seed-*.js. Do not hand-edit:
-- the next run overwrites it, and the site would keep the old values anyway.
-- To change something here, change the seed data and run the generator.
--
-- 17 sections, 84 items, 26 pours, 7 options, 62 copy fields.
--
-- Runs once, at Phase 3 step 6. The ids are derived from each row's position
-- in the seed data rather than generated, so this file is stable in a diff --
-- but it also means re-running it after reordering the menu would collide.
-- If it has to be applied twice, empty the tables first.
--
-- Not seeded here: the FAQ (18 entries, held pending the owner's answer on
-- the demo notice) and the photos (Phase 6 defines the slots).
-- ============================================================================

-- ---- sections --------------------------------------------------------------

-- ---- items -----------------------------------------------------------------
-- Prices are text, never numeric: 3.90 stored as a number renders as 3.9.

-- ---- pours (the "Bottle $60" lines) -----------------------------------------

-- ---- options (the crêpe toppings) -------------------------------------------
-- Modelled so nothing is lost on the way in. Not exposed in the editor.

-- ---- section copy ----------------------------------------------------------
-- Labels come from tools/copy-labels.mjs and are the owner's words, not keys.
-- max_length is set on the animated headlines only, and is provisional.

-- ---- did it all land? ------------------------------------------------------
-- A partial apply leaves a menu quietly missing its last section. This turns
-- that into an error at the moment it happens.
do $$
declare n integer;
begin
  select count(*) into n from public.menu_courses;
  if n <> 17 then raise exception 'menu_courses: expected 17 rows, found %', n; end if;
  select count(*) into n from public.menu_items;
  if n <> 84 then raise exception 'menu_items: expected 84 rows, found %', n; end if;
  select count(*) into n from public.menu_item_pours;
  if n <> 26 then raise exception 'menu_item_pours: expected 26 rows, found %', n; end if;
  select count(*) into n from public.menu_item_options;
  if n <> 7 then raise exception 'menu_item_options: expected 7 rows, found %', n; end if;
  select count(*) into n from public.site_copy;
  if n <> 62 then raise exception 'site_copy: expected 62 rows, found %', n; end if;
end $$;
