  ('441a99d9-73f3-56ee-8f28-9f7909a26d0f', '576a34df-e289-59ab-96e2-071d80bdd432', 'Morning Plate', null, 'Mixed greens with scrambled eggs, avocado, sour cream and toasted sourdough. Choice of cured meats or smoked salmon.', '21', null, null, false, null, 1),
  ('63559f33-73c6-53b7-89f3-232db61cff93', '576a34df-e289-59ab-96e2-071d80bdd432', 'Shakshuka', null, 'Poached eggs in a rich tomato and bell pepper sauce, finished with garlic, paprika and fresh herbs. Served with warm toasted sourdough.', '16', null, null, false, null, 2),
  ('d9056592-c497-5b97-9e36-b29532d34f68', '576a34df-e289-59ab-96e2-071d80bdd432', 'Breakfast Board for Two', null, 'A fresh mixed greens salad with scrambled eggs, avocado and olives, served with toasted sourdough, cream cheese, house-made sauce, jam and a dairy sweet. Choice of cured meats or smoked salmon.', '39', null, null, false, null, 3),
  ('58f9049f-8ceb-51d4-ae73-1ffb996a3fb2', '8ab2cabd-6099-5a61-9042-457adc096c8e', 'Assorted Pkhali', null, 'Georgian vegetable and eggplant rolls with walnut and Georgian spices, with homemade cornbread or bread.', '21', null, null, false, null, 1),
