  ('6729105f-aacd-5ffa-8fd4-2ee8394a497c', '8ab2cabd-6099-5a61-9042-457adc096c8e', 'Eggplant Rolls', null, 'Roasted eggplant filled with garlic-walnut sauce, topped with pomegranate.', '18', null, null, false, null, 3),
  ('a92b49e5-0ef2-5204-b8c1-c2cb4594f12d', '8ab2cabd-6099-5a61-9042-457adc096c8e', 'Arugula Salad with Goat Cheese', null, 'A fresh blend of arugula, strawberries, garlic and herbs, finished with oil and house-made dressing.', '19', null, null, false, null, 4),
  ('9097c6c3-49d0-5de6-b353-8226463f04a6', '8ab2cabd-6099-5a61-9042-457adc096c8e', 'The Georgian Salad', null, 'Tomatoes, cucumbers, onions, herbs and walnuts tossed in traditional sunflower oil and vinegar dressing.', '17', null, null, false, null, 5),
