  ('3147a50f-7b7a-5945-831a-bd776470c05a', 'ef721aad-8ca3-5c7e-aecc-f33a25579e58', 'Mint Mojito', null, 'Sparkling wine, fresh mint, lime.', '14', null, null, false, null, 5),
