  ('c534ae8b-033e-5755-b467-019643c89532', 'baa440a4-62dd-5745-a0f4-0a41110a01f8', 'Kisi Qvevri', null, 'Dry amber qvevri wine, Kakheti — honey and cinnamon aromas with notes of yellow and dried fruits.', '17', null, null, false, null, 3),
  ('3f613a0a-108b-51a3-9df5-c3e2067c6ef3', 'baa440a4-62dd-5745-a0f4-0a41110a01f8', 'Tsolikouri', null, 'Imereti dry white wine, with delicate aromas of yellow and white fruits.', '16', null, null, false, null, 4),
  ('d85c7d47-5304-5b75-94b3-68003c3e8bb6', 'baa440a4-62dd-5745-a0f4-0a41110a01f8', 'Tvishi', null, 'Naturally semi-sweet, Lechkhumi — yellow and tropical fruit aromas with citrus undertones.', '16', null, null, false, null, 5),
