  ('1b29ba10-a0ba-5dc1-8bba-45fcced4249e', 'be178dde-3b22-53d9-a88e-9aea7042eb22', 'Mtsvane', '2022', 'Single vineyard Kakheti, Manavi Wines. Dry white with crisp green apple, juicy pear and delicate floral notes.', '16', null, null, false, null, 1),
  ('c5007111-3974-53e6-80c4-39f0a1ef670e', 'be178dde-3b22-53d9-a88e-9aea7042eb22', 'Rkatsiteli', '2023', 'Khvitsia Wine, Kardenakhi — Kakheti. Dry white with lively acidity and floral hints.', '17', null, null, false, null, 2),
  ('e73844af-e931-5453-a9d6-ee52b72c070b', 'be178dde-3b22-53d9-a88e-9aea7042eb22', 'Kisi', '2020', 'Kakheti, Vellino. Dry amber with ripe apricot and peach, floral hints and a touch of citrus.', '18', null, null, false, null, 3),
  ('37498d05-4bed-593a-91ae-aa4fef1c0f30', 'be178dde-3b22-53d9-a88e-9aea7042eb22', 'Mtsvane', '2020', 'Kakheti. Dry amber with primary aromas of lemon, lime and green apple, with notes of tropical fruit.', '17', null, null, false, null, 4),
