  ('d4191b99-3e5d-5d98-97ec-827e7d7e8a05', 'c1c26fc2-cf3e-573f-b09e-ca13e4924f79', 'Mukuzani', null, 'Dry red from Kakheti — rich dark berry aromas with hints of oak and spice.', '18', null, null, false, null, 4),
  ('265d561e-23d3-52cc-9da9-e7e2f195c8c1', 'b4b87b25-b782-523d-8ccf-4fcb26e58921', 'Barbera d’Asti', null, 'Piedmont — rich with floral tones of iris and rose, with hints of undergrowth, raspberry and plum.', '15', null, null, false, null, 1),
  ('e4175bd7-9ec9-57f1-b2ef-a6825d42776d', 'b4b87b25-b782-523d-8ccf-4fcb26e58921', 'Friularo', null, 'An elegant red with an intense aroma, featuring spicy notes, violet and sour cherry.', '17', null, null, false, null, 2),
  ('541f1c3f-13ab-5d10-968e-53bfe11a2ac3', 'b4b87b25-b782-523d-8ccf-4fcb26e58921', 'Sauvignon Blanc', null, 'Elegant and balanced, crisp acidity and flowers on the nose, with white peach, grapefruit, tropical fruit and citrus.', '18', null, null, false, null, 3),
  ('738eb521-0f4c-566e-bd43-585454bee99d', 'b4b87b25-b782-523d-8ccf-4fcb26e58921', 'Falanghina del Sannio', null, 'Aromatic notes of ripe apple and citrus blossom, hints of pear, peach and crushed stone, crisp with a refreshing structure.', '18', null, null, false, null, 4),
  ('2cd251f2-db1e-5798-b17c-45581ad38b22', 'b4b87b25-b782-523d-8ccf-4fcb26e58921', 'Chardonnay', null, 'Structured and fresh, with hints of apricot and green apple — intense and refined, with a robust finish.', '18', null, null, false, null, 5),
  ('93148e6b-02bf-5bfc-bc9b-5a2ba590589b', 'b4b87b25-b782-523d-8ccf-4fcb26e58921', 'Prosecco Brut', null, 'Very fine and elegant, floral and fruity, with hints of acacia flower, green apple and almond. Dry, fresh, lively on the palate.', '16', null, null, false, null, 6),
  ('9362922a-0e16-56ea-9df2-da761f7c03c5', 'b4b87b25-b782-523d-8ccf-4fcb26e58921', 'Corona Extra', '12 oz', null, '6.50', null, null, false, null, 7),
  ('a9437669-db42-5f3b-9ef4-3a27a23d2e09', 'b4b87b25-b782-523d-8ccf-4fcb26e58921', 'Heineken', '12 oz', null, '6', null, null, false, null, 8),
  ('db5c44d1-763a-58db-b03a-d63fac16ef36', '7e57b1ba-3e8d-5b12-b7ef-5356da011928', 'Aromati’s Charcuterie & Cheese Board', null, 'A selection of cured meats and artisan cheeses, served with fresh fruit, olives, nuts, jam and crackers.', null, null, null, true, null, 1),
  ('dcd8297f-a8b5-50b4-9a6b-aa99c25d4b19', '7e57b1ba-3e8d-5b12-b7ef-5356da011928', 'Cheese Board', null, 'Chef’s selection of artisan cheeses, served with croutons, fresh fruit, nuts and jam.', null, null, null, true, null, 2);
