insert into public.site_copy (key, page, section, label, help, value, max_length, sort_order) values
  ('hero.eyebrow', 'index', 'Hero', 'Small line above the name', null, 'Murray Hill · Manhattan', null, 10),
  ('hero.sub', 'index', 'Hero', 'Line under the name', 'The wide spacing around the ✦ is deliberate — keep it if you edit this.', 'Café  ✦  Wine Bar', null, 20),
  ('hero.desc', 'index', 'Hero', 'Opening sentence', 'Starting a new line here puts one on the page.', E'Two floors on East 34th Street where Georgian cooking,\nnatural wine and coffee share one table.', null, 30),
  ('hero.ctaPrimary', 'index', 'Hero', 'First button', null, 'See the Menus', null, 40),
  ('hero.ctaSecondary', 'index', 'Hero', 'Second button', null, 'The Wine Bar', null, 50),
  ('story.label', 'index', 'The Idea', 'Section tag', null, 'The Idea', null, 60),
  ('story.headline', 'index', 'The Idea', 'Headline', null, 'Georgian cooking for a Manhattan morning.', 72, 70),
  ('story.lead', 'index', 'The Idea', 'Opening paragraph', 'Put *asterisks* around words to set them in italic.', 'Aromati, from the Georgian word for *aroma*, is a bi-level café and wine bar in Murray Hill, where American coffee culture meets the oldest food and wine traditions in Europe.', null, 80),
  ('story.body', 'index', 'The Idea', 'Second paragraph', null, 'Downstairs, an open kitchen and coffee bar move at the pace of the city: espresso pulled, matcha whisked, khachapuri blistering in the oven. Upstairs, the room slows down into burgundy walls, tufted leather, cane and oak, and low globe light, a dining room and wine bar built for long evenings.', null, 90),
  ('story.quote', 'index', 'The Idea', 'Pull quote', null, 'Georgia has been making wine for eight thousand years. We think it belongs at the table, whatever the occasion.', null, 100),
  ('kitchen.label', 'index', 'The Kitchen', 'Section tag', null, 'The Kitchen', null, 110),
  ('kitchen.headline', 'index', 'The Kitchen', 'Headline', null, 'Bread, cheese, and broth: a few staples of the Georgian table.', 72, 120),
  ('kitchen.lede', 'index', 'The Kitchen', 'Paragraph under the headline', null, 'Everything comes out of the open kitchen on the ground floor. Khachapuri is blistered to order and khinkali is pleated by hand.', null, 130),
  ('kitchen.reelLabel', 'index', 'The Kitchen', 'Caption above the photo strip', null, 'A few plates', null, 140),
  ('kitchen.reelNote', 'index', 'The Kitchen', 'Small note beside the caption', null, 'photographed in the room', null, 150),
  ('cafe.label', 'index', 'The Café', 'Section tag', null, 'The Café', null, 160),
  ('cafe.headline', 'index', 'The Café', 'Headline', null, 'Downstairs runs on espresso.', 72, 170),
  ('cafe.lede', 'index', 'The Café', 'Paragraph under the headline', null, 'The ground floor is a New York coffee bar with espresso drinks, matcha, and pastries for the morning.', null, 180),
  ('cafe.card1.title', 'index', 'The Café', 'Card 1 — drink', null, 'Tiramisu Latte', null, 190),
  ('cafe.card1.note', 'index', 'The Café', 'Card 1 — description', null, 'mascarpone cream, cocoa, a ladyfinger on top', null, 200),
  ('cafe.card2.title', 'index', 'The Café', 'Card 2 — drink', null, 'Maple Syrup Iced Latte', null, 210),
  ('cafe.card2.note', 'index', 'The Café', 'Card 2 — description', null, 'topped with silky maple cold foam', null, 220),
  ('cafe.card3.title', 'index', 'The Café', 'Card 3 — drink', null, 'Fruit Matchas', null, 230),
  ('cafe.card3.note', 'index', 'The Café', 'Card 3 — description', null, 'strawberry, mango & blueberry, layered over ice', null, 240),
  ('cafe.card4.title', 'index', 'The Café', 'Card 4 — drink', null, 'The Classics', null, 250),
  ('cafe.card4.note', 'index', 'The Café', 'Card 4 — description', null, 'flat whites & cappuccinos, poured properly', null, 260),
  ('cafe.cta', 'index', 'The Café', 'Sentence above the button', null, 'The drinks menu includes espresso, matcha, chai, smoothies, and cold drinks.', null, 270),
  ('cafe.ctaButton', 'index', 'The Café', 'Button', null, 'See the Drinks Menu', null, 280),
  ('wine.label', 'index', 'The Wine Bar', 'Section tag', null, 'The Wine Bar', null, 290),
  ('wine.headline', 'index', 'The Wine Bar', 'Headline', null, 'A wine list shaped by Georgia.', 72, 300),
  ('wine.lede', 'index', 'The Wine Bar', 'Paragraph under the headline', null, 'Upstairs, the list brings together qvevri ambers, Saperavi, natural wines, and a short European selection. Wines are available by the glass or bottle, with pairings for the table.', null, 310),
  ('wine.note1.title', 'index', 'The Wine Bar', 'Note 1 — title', null, 'Amber', null, 320),
  ('wine.note1.text', 'index', 'The Wine Bar', 'Note 1 — description', null, 'Amber wines bring notes of honey, spice, dried fruit, and citrus.', null, 330),
  ('wine.note2.title', 'index', 'The Wine Bar', 'Note 2 — title', null, 'Saperavi', null, 340),
  ('wine.note2.text', 'index', 'The Wine Bar', 'Note 2 — description', null, 'Saperavi is a Georgian red with dark berry, plum, and cherry notes.', null, 350),
  ('wine.note3.title', 'index', 'The Wine Bar', 'Note 3 — title', null, 'Qvevri', null, 360),
  ('wine.note3.text', 'index', 'The Wine Bar', 'Note 3 — description', null, 'The list includes qvevri wines in both amber and red styles.', null, 370),
  ('wine.hours', 'index', 'The Wine Bar', 'Small line about the room', null, 'Second floor · wine bar', null, 380),
  ('wine.ctaButton', 'index', 'The Wine Bar', 'Button', null, 'Read the Wine List', null, 390),
  ('gallery.label', 'index', 'The Room', 'Section tag', null, 'The Room', null, 400),
  ('gallery.headline', 'index', 'The Room', 'Headline', null, 'Cane, leather, burgundy — and light that lingers.', 72, 410),
  ('visit.label', 'index', 'Visit', 'Section tag', null, 'Visit', null, 420),
  ('visit.headline', 'index', 'Visit', 'Headline', 'Starting a new line here puts one on the page.', E'Come say hello,\nMurray Hill.', 72, 430),
  ('food.label', 'food', 'Food menu', 'Section tag', null, 'The Kitchen', null, 440),
  ('food.headline', 'food', 'Food menu', 'Page title', null, 'The Food Menu', 32, 450),
  ('food.lede', 'food', 'Food menu', 'Paragraph under the title', null, 'Everything comes out of the open kitchen on the ground floor. Khachapuri is blistered to order and khinkali is pleated by hand. Served all day.', null, 460),
  ('food.footNote', 'food', 'Food menu', 'Note at the foot of the menu', null, '…and salads, stews, toast & sweets in between.', null, 470),
  ('food.footButton', 'food', 'Food menu', 'Button at the foot of the menu', null, 'Come Hungry', null, 480),
  ('drinks.label', 'drinks', 'Drinks menu', 'Section tag', null, 'The Café', null, 490),
  ('drinks.headline', 'drinks', 'Drinks menu', 'Page title', null, 'Hot & Cold Drinks', 32, 500),
  ('drinks.lede', 'drinks', 'Drinks menu', 'Paragraph under the title', null, 'The ground floor is a New York coffee bar: espresso pulled properly, matcha whisked to order, smoothies blended fresh. From seven in the morning.', null, 510),
  ('drinks.footNote', 'drinks', 'Drinks menu', 'Note at the foot of the menu', null, 'Ask about drink customizations.', null, 520),
  ('drinks.footButton', 'drinks', 'Drinks menu', 'Button at the foot of the menu', null, 'Find the Café', null, 530),
  ('wineList.label', 'wine', 'Wine list', 'Section tag', null, 'The Wine Bar', null, 540),
  ('wineList.headline', 'wine', 'Wine list', 'Page title', null, 'The Wine List', 32, 550),
  ('wineList.lede', 'wine', 'Wine list', 'Paragraph under the title', null, 'Qvevri ambers, Saperavi and natural bottles chosen for the table, alongside a short European list. Poured by the glass or the bottle on the second floor.', null, 560),
  ('wineList.footNote', 'wine', 'Wine list', 'Note at the foot of the list', null, 'Wines are available by the glass or bottle. The selection may change.', null, 570),
  ('wineList.footButton', 'wine', 'Wine list', 'Button at the foot of the list', null, 'Plan a Visit', null, 580),
  ('faq.label', 'faq', 'FAQ page', 'Section tag', null, 'Good to Know', null, 590),
  ('faq.headline', 'faq', 'FAQ page', 'Page title', null, 'Questions, answered.', 32, 600),
  ('faq.lede', 'faq', 'FAQ page', 'Paragraph under the title', null, 'The things guests ask most often — when to come, what the upstairs room is like, and how to plan something bigger than a table for two.', null, 610),
  ('faq.footNote', 'faq', 'FAQ page', 'Note at the foot of the page', null, 'Still wondering? Call us — someone is always in.', null, 620);
